function initTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(o=>{o.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active"),e.setAttribute("aria-selected","false")}),t.forEach(e=>e.classList.remove("active")),o.classList.add("active"),o.setAttribute("aria-selected","true");const i=o.getAttribute("data-tab"),r=document.getElementById(i);r&&r.classList.add("active")})})}function initQuiz(){const e=document.getElementById("khambhat-quiz-form"),t=document.getElementById("quiz-result"),o={q1:"2",q2:"1"};e&&e.addEventListener("submit",i=>{i.preventDefault();let r=0;const a=new FormData(e);for(let[e,t]of a.entries())o[e]===t&&r++;const n=Object.keys(o).length;r===n?(t.textContent=`🎉 Perfect! You scored ${r}/${n}. You are a Khambhat expert!`,t.style.color="green"):(t.textContent=`You scored ${r}/${n}. Keep exploring!`,t.style.color="orange")})}function initGalleryModal(){const e=document.getElementById("gallery-modal"),t=document.getElementById("modal-title"),o=document.getElementById("modal-desc"),i=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(i=>{i.addEventListener("click",()=>{const r=i.getAttribute("data-title"),a=i.getAttribute("data-desc");t.textContent=r,o.textContent=a,e.classList.add("active"),e.setAttribute("aria-hidden","false")})}),i&&i.addEventListener("click",()=>{e.classList.remove("active"),e.setAttribute("aria-hidden","true")}),window.addEventListener("click",t=>{t.target===e&&e.classList.remove("active")})}function initScrollTop(){const e=document.getElementById("btn-scroll-top");e&&(window.addEventListener("scroll",()=>{window.scrollY>300?e.classList.add("visible"):e.classList.remove("visible")}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("khambhat-port-explorer/index.html",[{id:"khambhat-overview",title:"Khambhat Historical Overview",description:"Learn about the history of Cambay port.",link:"khambhat-port-explorer/index.html#overview"},{id:"khambhat-archaeology",title:"Khambhat Underwater Archaeology",description:"Discover the submerged ruins of the Gulf of Khambhat.",link:"khambhat-port-explorer/index.html#archaeology"},{id:"khambhat-exports",title:"Agate & Carnelian Industry",description:"The famous gemstone exports of Khambhat.",link:"khambhat-port-explorer/index.html#exports"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});